class API:
    """API-layer actions."""

    @staticmethod
    def login(username, password):
        """Validates credentials."""
        if not username:
            return {"ok": False, "error": "Username is required"}

        if not password:
            return {"ok": False, "error": "Password is required"}

        user = DB.users.get(username)
        if not user or user["password"] != password:
            return {"ok": False, "error": "Invalid username or password"}

        return {"ok": True, "user": username}

    @staticmethod
    def logout():
        """Logs out current user."""
        return {"ok": True}

    @staticmethod
    def search_books(term):
        """Searches for books matching term."""
        results = []
        search_term = term.lower() if term else ""

        for book in DB.books.values():
            if not term or search_term in book["title"].lower() or search_term in book["author"].lower() or search_term in book["isbn"].lower():
                availability_status = "Available" if book["available_copies"] > 0 else "Not Available"
                results.append({
                    "book_id": book["book_id"],
                    "title": book["title"],
                    "author": book["author"],
                    "isbn": book["isbn"],
                    "availability_status": availability_status,
                    "available_copies": book["available_copies"],
                    "total_copies": book["total_copies"]
                })

        return {"ok": True, "books": results}

    @staticmethod
    def get_book_details(book_id):
        """Returns details for specified book_id."""
        book = DB.books.get(book_id)
        if not book:
            return {"ok": False, "error": "Book not found"}

        availability_status = "Available" if book["available_copies"] > 0 else "Not Available"
        return {
            "ok": True,
            "book": {
                "book_id": book["book_id"],
                "title": book["title"],
                "author": book["author"],
                "isbn": book["isbn"],
                "availability_status": availability_status,
                "available_copies": book["available_copies"],
                "total_copies": book["total_copies"]
            }
        }

    @staticmethod
    def borrow_book(username, book_id):
        """Attempts to borrow book for user."""
        book = DB.books.get(book_id)
        if not book:
            return {"ok": False, "error": "Book not found"}

        if book["available_copies"] <= 0:
            return {"ok": False, "error": "No copies available"}

        existing = Database.get_borrowing(username, book_id)
        if existing:
            return {"ok": False, "error": "You have already borrowed this book"}

        count = Database.count_user_borrowings(username)
        if count >= CONFIG["borrowing_limit"]:
            return {"ok": False, "error": "You have reached your borrowing limit"}

        DB.borrowings.append({
            "username": username,
            "book_id": book_id,
            "borrow_date": CONFIG["current_date"],
            "due_date": CONFIG["due_date"]
        })
        book["available_copies"] -= 1

        return {"ok": True, "borrow_date": CONFIG["current_date"], "due_date": CONFIG["due_date"]}

    @staticmethod
    def return_book(username, book_id):
        """Attempts to return book for user."""
        borrowing = Database.get_borrowing(username, book_id)
        if not borrowing:
            return {"ok": False, "error": "You have not borrowed this book"}

        DB.borrowings = [b for b in DB.borrowings if not (b["username"] == username and b["book_id"] == book_id)]
        book = DB.books.get(book_id)
        if book:
            book["available_copies"] += 1

        return {"ok": True}

    @staticmethod
    def get_borrowed_books(username):
        """Returns list of books currently borrowed by the specified user."""
        books = []
        for borrowing in DB.borrowings:
            if borrowing["username"] == username:
                book = DB.books.get(borrowing["book_id"])
                if book:
                    books.append({
                        "book_id": book["book_id"],
                        "title": book["title"],
                        "author": book["author"],
                        "borrow_date": borrowing["borrow_date"],
                        "due_date": borrowing["due_date"]
                    })
        return {"ok": True, "books": books}


class Database:
    """Direct DB-layer access, for verifying what was really stored."""

    @staticmethod
    def get_user(username):
        """Returns user record from database for specified username, or None if user doesn't exist."""
        user = DB.users.get(username)
        return dict(user) if user else None

    @staticmethod
    def get_book(book_id):
        """Returns book record from database for specified book_id, or None if book doesn't exist."""
        book = DB.books.get(book_id)
        return dict(book) if book else None

    @staticmethod
    def get_all_books():
        """Returns all book records from database."""
        return [dict(book) for book in DB.books.values()]

    @staticmethod
    def get_borrowing(username, book_id):
        """Returns borrowing record for specified user and book if it exists and is active, or None otherwise."""
        for borrowing in DB.borrowings:
            if borrowing["username"] == username and borrowing["book_id"] == book_id:
                return dict(borrowing)
        return None

    @staticmethod
    def get_all_borrowings(username):
        """Returns all active borrowing records for specified username."""
        return [dict(b) for b in DB.borrowings if b["username"] == username]

    @staticmethod
    def count_user_borrowings(username):
        """Returns count of active borrowing records for specified username."""
        return sum(1 for b in DB.borrowings if b["username"] == username)


